79:     async retrieveRawTransaction(txid: string) {
80:         const checkTxnRegex = (txn: string) => {
81:             const re = /^([A-Fa-f0-9]{2}){61,}$/;
82:             if (!re.test(txn)) {
83:                 throw Error(`Regex failed for retrieved transaction, got: ${txn}`);
84:             }
85:         };
86:         if (!this.cachedRawTransactions[txid]) {
87:             this.cachedRawTransactions[txid] = "waiting";
88:             const txns = await this.getRawTransactions([txid]);
89:             if (!txns || txns.length === 0 || typeof txns[0] !== "string") {
90:                 throw Error(`Response error in getRawTransactions, got: ${txns}`);
91:             }
92:             checkTxnRegex(txns[0]);
93:             this.cachedRawTransactions[txid] = txns[0];
94:             return txns[0];
95:         } else {
96:             checkTxnRegex(this.cachedRawTransactions[txid]);
97:             return this.cachedRawTransactions[txid];
98:         }
